/**
 * FanetGraph — the UAV infrastructure network (FANET) rendered as a
 * graph, from the architecture in the live mission state.
 *
 * Uses SVG for testability and crisp scaling. Layout is layered:
 * satellites on top, UAVs in the middle, ground stations on the bottom.
 * Edges are drawn between layer nodes by the architecture's link_list.
 *
 * Epistemic tagging: the architecture is generated by the CLEAR-D
 * discovery loop; Section 21 category is simulation_result.
 */

import { useMemo, useState } from "react"
import { TaggedOutput } from "../../components/EpistemicBadge/EpistemicBadge"
import type { MissionNode, MissionState } from "../MissionControl/missionApi"
import { useMission } from "../MissionControl/missionContext"

const VIEW_W = 960
const VIEW_H = 520
const LAYER_Y = { satellite: 90, uav: 260, ground: 440 }

const NODE_COLOR: Record<string, string> = {
  Satellite_LEO: "var(--color-accent-teal)",
  Satellite_GEO: "var(--color-accent-teal)",
  UAV_Energy: "var(--color-accent-violet)",
  UAV_Compute: "var(--color-accent-amber)",
  Ground_Station: "var(--color-accent-slate)",
}

const LINK_COLOR: Record<string, string> = {
  Laser_Link: "#8b5cf6",
  Microwave_Link: "#f59e0b",
  Hybrid_Link: "#ec4899",
}

function layerOf(node: MissionNode): keyof typeof LAYER_Y {
  if (node.kind.startsWith("Satellite_")) return "satellite"
  if (node.kind.startsWith("UAV_")) return "uav"
  return "ground"
}

function groupByLayer(
  nodes: MissionNode[],
): Record<keyof typeof LAYER_Y, MissionNode[]> {
  const out = { satellite: [], uav: [], ground: [] } as Record<
    keyof typeof LAYER_Y,
    MissionNode[]
  >
  for (const n of nodes) {
    out[layerOf(n)].push(n)
  }
  return out
}

export function FanetGraph() {
  const { state: load, refresh } = useMission()

  return (
    <section aria-labelledby="fanet-heading" className="mb-10">
      <div className="mb-1 flex items-baseline gap-3">
        <h2 id="fanet-heading" className="text-lg font-medium">
          UAV Network (FANET)
        </h2>
        <span className="text-xs opacity-50">
          Section 10 / 12 · live mission topology
        </span>
      </div>
      <p className="mb-4 text-sm opacity-70 max-w-3xl">
        The directed graph of nodes and links for the current mission
        architecture. UAVs in the middle layer, satellites above, ground
        stations below. Edges are the architecture&apos;s modalities.
      </p>

      {load.status === "loading" && (
        <p className="text-sm opacity-60" data-testid="fanet-loading">
          Loading mission topology…
        </p>
      )}

      {load.status === "error" && (
        <div className="rounded border border-current/15 p-4" data-testid="fanet-error">
          <p className="text-sm" style={{ color: "var(--color-accent-amber)" }}>
            Error{load.status_code ? ` (${load.status_code})` : ""}: {load.message}
          </p>
          <button
            type="button"
            onClick={refresh}
            className="mt-3 rounded border px-3 py-1 text-xs hover:bg-current/5"
          >
            Retry
          </button>
        </div>
      )}

      {load.status === "ok" && <GraphView data={load.data} onRefresh={refresh} />}
    </section>
  )
}

function GraphView({ data, onRefresh }: { data: MissionState; onRefresh: () => void }) {
  const nodes = data.architecture.node_list
  const links = data.architecture.link_list
  const layers = useMemo(() => groupByLayer(nodes), [nodes])

  // Assign positions: even horizontal distribution within each layer.
  const positions = useMemo(() => {
    const p: Record<string, { x: number; y: number }> = {}
    for (const layer of ["satellite", "uav", "ground"] as const) {
      const list = layers[layer]
      const n = list.length
      const y = LAYER_Y[layer]
      for (let i = 0; i < n; i++) {
        const x = ((i + 1) / (n + 1)) * VIEW_W
        p[list[i].node_id] = { x, y }
      }
    }
    return p
  }, [layers])

  const [hovered, setHovered] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)

  const nodeById = useMemo(() => {
    const m: Record<string, MissionNode> = {}
    for (const n of nodes) m[n.node_id] = n
    return m
  }, [nodes])

  const selectedNode = selected ? nodeById[selected] ?? null : null
  const selectedLinks = useMemo(() => {
    if (!selected) return []
    return links.filter((l) => l.source_id === selected || l.target_id === selected)
  }, [links, selected])

  if (nodes.length === 0) {
    return (
      <TaggedOutput tag="simulation_result" className="rounded border border-current/15 p-4">
        <p className="text-sm opacity-60">No nodes in the current architecture.</p>
      </TaggedOutput>
    )
  }

  return (
    <TaggedOutput tag="simulation_result" className="rounded border border-current/15 p-4">
      <div className="mb-3 flex flex-wrap items-baseline gap-3 text-xs opacity-70">
        <span className="font-mono">{nodes.length} nodes</span>
        <span className="font-mono">{links.length} links</span>
        <span className="font-mono">verdict: {data.architecture.sat_verdict}</span>
        <span className="font-mono">ε: {data.architecture.epsilon_bound.toExponential(2)}</span>
        <button
          type="button"
          onClick={onRefresh}
          className="ml-auto rounded border border-current/20 px-2 py-0.5 text-[0.65rem] uppercase tracking-wider hover:bg-current/5"
        >
          Refresh
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-[1fr_280px] gap-4">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          style={{ width: "100%", height: "auto", maxHeight: 500 }}
          role="img"
          aria-label="UAV network graph"
          data-testid="fanet-svg"
        >
          <defs>
            <marker
              id="arrow"
              viewBox="0 0 10 10"
              refX="10"
              refY="5"
              markerWidth="6"
              markerHeight="6"
              orient="auto-start-reverse"
            >
              <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor" opacity="0.7" />
            </marker>
          </defs>

          {/* Edges first so nodes are drawn on top. */}
          {links.map((ln) => {
            const a = positions[ln.source_id]
            const b = positions[ln.target_id]
            if (!a || !b) return null
            const color = LINK_COLOR[ln.kind] ?? "#9ca3af"
            const isEmphasized =
              hovered === ln.source_id ||
              hovered === ln.target_id ||
              selected === ln.source_id ||
              selected === ln.target_id
            return (
              <line
                key={ln.link_id}
                data-testid={`fanet-edge-${ln.link_id}`}
                data-link-kind={ln.kind}
                x1={a.x}
                y1={a.y}
                x2={b.x}
                y2={b.y}
                stroke={color}
                strokeWidth={isEmphasized ? 3 : 1.5}
                strokeOpacity={isEmphasized ? 1 : 0.5}
                markerEnd="url(#arrow)"
                style={{ color }}
              />
            )
          })}

          {/* Layer labels. */}
          <text x={8} y={LAYER_Y.satellite - 30} fontSize={11} opacity={0.5}>
            SATELLITES
          </text>
          <text x={8} y={LAYER_Y.uav - 30} fontSize={11} opacity={0.5}>
            UAVS
          </text>
          <text x={8} y={LAYER_Y.ground - 30} fontSize={11} opacity={0.5}>
            GROUND
          </text>

          {/* Nodes. */}
          {nodes.map((n) => {
            const p = positions[n.node_id]
            if (!p) return null
            const color = NODE_COLOR[n.kind] ?? "#9ca3af"
            const isSelected = selected === n.node_id
            const isHovered = hovered === n.node_id
            const isUav = n.kind.startsWith("UAV_")
            const battery = isUav ? n.params.battery_pct ?? null : null
            const r = isUav
              ? 12 + (battery !== null ? (battery / 100) * 4 : 0)
              : 16
            return (
              <g
                key={n.node_id}
                data-testid={`fanet-node-${n.node_id}`}
                data-node-kind={n.kind}
                onMouseEnter={() => setHovered(n.node_id)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => setSelected((s) => (s === n.node_id ? null : n.node_id))}
                style={{ cursor: "pointer" }}
              >
                <circle
                  cx={p.x}
                  cy={p.y}
                  r={r}
                  fill={color}
                  stroke={isSelected || isHovered ? "white" : "transparent"}
                  strokeWidth={isSelected || isHovered ? 2 : 0}
                  opacity={0.9}
                />
                <text
                  x={p.x}
                  y={p.y + r + 14}
                  textAnchor="middle"
                  fontSize={10}
                  opacity={0.7}
                  style={{ pointerEvents: "none" }}
                >
                  {n.node_id}
                </text>
                <text
                  x={p.x}
                  y={p.y + 4}
                  textAnchor="middle"
                  fontSize={9}
                  fill="white"
                  style={{ pointerEvents: "none" }}
                >
                  {n.kind.replace("UAV_", "").replace("Satellite_", "").replace("Ground_", "")[0]}
                </text>
              </g>
            )
          })}
        </svg>

        <aside className="text-xs">
          {!selectedNode && (
            <p className="opacity-60">Click a node to inspect it.</p>
          )}
          {selectedNode && (
            <div className="rounded border border-current/15 p-3" data-testid="fanet-inspector">
              <div className="mb-1 font-mono font-medium">{selectedNode.node_id}</div>
              <div className="mb-2 opacity-70">{selectedNode.kind}</div>
              {Object.keys(selectedNode.params).length > 0 && (
                <table className="w-full">
                  <tbody>
                    {Object.entries(selectedNode.params).map(([k, v]) => (
                      <tr key={k}>
                        <td className="py-0.5 opacity-60 font-mono">{k}</td>
                        <td className="py-0.5 text-right font-mono">
                          {typeof v === "number" ? v.toFixed(2) : String(v)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
              {selectedLinks.length > 0 && (
                <div className="mt-2 border-t border-current/10 pt-2">
                  <div className="mb-1 opacity-60">links ({selectedLinks.length})</div>
                  <ul className="space-y-0.5">
                    {selectedLinks.map((l) => (
                      <li key={l.link_id} className="font-mono">
                        {l.source_id} → {l.target_id}{" "}
                        <span className="opacity-60">({l.kind})</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </aside>
      </div>

      <footer className="mt-4 border-t border-current/10 pt-3 font-mono text-xs opacity-60">
        artefact: fanet_architecture
      </footer>
    </TaggedOutput>
  )
}
